59	/**
60	 * This Invoker works on Consumer side.
61	 */
62	public abstract class AbstractInvoker<T> implements Invoker<T> {
63	
64	    protected static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(AbstractInvoker.class);
65	
66	    /**
67	     * Service interface type
68	     */
69	    private final Class<T> type;
70	
71	    /**
72	     * {@link Node} url
73	     */
74	    private final URL url;
75	
76	    /**
77	     * {@link Invoker} default attachment
78	     */
79	    private final Map<String, Object> attachment;
80	
81	    protected final String version;
82	
83	    /**
84	     * {@link Node} available
85	     */
86	    private volatile boolean available = true;
87	
88	    /**
89	     * {@link Node} destroy
90	     */
91	    private volatile boolean destroyed = false;
92	
93	    /**
94	     * Whether set future to Thread Local when invocation mode is sync
95	     */
96	    private static final boolean setFutureWhenSync = Boolean.parseBoolean(SystemPropertyConfigUtils.getSystemProperty(
97	            CommonConstants.ThirdPartyProperty.SET_FUTURE_IN_SYNC_MODE, "true"));
98	
99	    // -- Constructor
100	
101	    public AbstractInvoker(Class<T> type, URL url) {
102	        this(type, url, (Map<String, Object>) null);
103	    }
104	
105	    public AbstractInvoker(Class<T> type, URL url, String[] keys) {
106	        this(type, url, convertAttachment(url, keys));
107	    }
108	
109	    public AbstractInvoker(Class<T> type, URL url, Map<String, Object> attachment) {
110	        if (type == null) {
111	            throw new IllegalArgumentException("service type == null");
112	        }
113	        if (url == null) {
114	            throw new IllegalArgumentException("service url == null");
115	        }
116	        this.type = type;
117	        this.url = url;
118	
119	        this.attachment = attachment == null ? null : Collections.unmodifiableMap(attachment);
120	        this.version = url.getVersion(DEFAULT_VERSION);
121	    }
122	
123	    private static Map<String, Object> convertAttachment(URL url, String[] keys) {
124	        if (ArrayUtils.isEmpty(keys)) {
125	            return null;
126	        }
127	        Map<String, Object> attachment = new HashMap<>(keys.length);
128	        for (String key : keys) {
129	            String value = url.getParameter(key);
130	            if (value != null && value.length() > 0) {
131	                attachment.put(key, value);
132	            }
133	        }
134	        return attachment;
135	    }
136	
137	    // -- Public api
138	
139	    @Override
140	    public Class<T> getInterface() {
141	        return type;
142	    }
143	
144	    @Override
145	    public URL getUrl() {
146	        return url;
147	    }
148	
149	    @Override
150	    public boolean isAvailable() {
151	        return available;
152	    }
153	
154	    @Override
155	    public void destroy() {
156	        this.destroyed = true;
157	        setAvailable(false);
158	    }
159	
160	    protected void setAvailable(boolean available) {
161	        this.available = available;
162	    }
163	
164	    public boolean isDestroyed() {
165	        return destroyed;
166	    }
167	
168	    @Override
169	    public String toString() {
170	        return getInterface() + " -> " + (getUrl() == null ? "" : getUrl().getAddress());
171	    }
172	
173	    @Override
174	    public Result invoke(Invocation inv) throws RpcException {
175	        // if invoker is destroyed due to address refresh from registry, let's allow the current invoke to proceed
176	        if (isDestroyed()) {
177	            logger.warn(
178	                    PROTOCOL_FAILED_REQUEST,
179	                    "",
180	                    "",
181	                    "Invoker for service " + this + " on consumer " + NetUtils.getLocalHost() + " is destroyed, "
182	                            + ", dubbo version is " + Version.getVersion()
183	                            + ", this invoker should not be used any longer");
184	        }
185	
186	        RpcInvocation invocation = (RpcInvocation) inv;
187	
188	        // prepare rpc invocation
189	        prepareInvocation(invocation);
190	
191	        // do invoke rpc invocation and return async result
192	        AsyncRpcResult asyncResult = doInvokeAndReturn(invocation);
193	
194	        // wait rpc result if sync
195	        waitForResultIfSync(asyncResult, invocation);
196	
197	        return asyncResult;
198	    }
199	
200	    private void prepareInvocation(RpcInvocation inv) {
201	        inv.setInvoker(this);
202	
203	        addInvocationAttachments(inv);
204	
205	        inv.setInvokeMode(RpcUtils.getInvokeMode(url, inv));
206	
207	        RpcUtils.attachInvocationIdIfAsync(getUrl(), inv);
208	
209	        attachInvocationSerializationId(inv);
210	    }
211	
212	    /**
213	     * Attach Invocation Serialization id
214	     * <p>
215	     *     <ol>
216	     *         <li>Obtain the value from <code>prefer_serialization</code></li>
217	     *         <li>If the preceding information is not obtained, obtain the value from <code>serialization</code></li>
218	     *         <li>If neither is obtained, use the default value</li>
219	     *     </ol>
220	     * </p>
221	     *
222	     * @param inv inv
223	     */
224	    private void attachInvocationSerializationId(RpcInvocation inv) {
225	        Byte serializationId = UrlUtils.serializationId(getUrl());
226	
227	        if (serializationId != null) {
228	            inv.put(SERIALIZATION_ID_KEY, serializationId);
229	        }
230	    }
231	
232	    private void addInvocationAttachments(RpcInvocation invocation) {
233	        // invoker attachment
234	        if (CollectionUtils.isNotEmptyMap(attachment)) {
235	            invocation.addObjectAttachmentsIfAbsent(attachment);
236	        }
237	
238	        // client context attachment
239	        Map<String, Object> clientContextAttachments =
240	                RpcContext.getClientAttachment().getObjectAttachments();
241	        if (CollectionUtils.isNotEmptyMap(clientContextAttachments)) {
242	            invocation.addObjectAttachmentsIfAbsent(clientContextAttachments);
243	        }
244	    }
245	
246	    private AsyncRpcResult doInvokeAndReturn(RpcInvocation invocation) {
247	        AsyncRpcResult asyncResult;
248	        try {
249	            asyncResult = (AsyncRpcResult) doInvoke(invocation);
250	        } catch (InvocationTargetException e) {
251	            Throwable te = e.getTargetException();
252	            if (te != null) {
253	                // if biz exception
254	                if (te instanceof RpcException) {
255	                    ((RpcException) te).setCode(RpcException.BIZ_EXCEPTION);
256	                }
257	                asyncResult = AsyncRpcResult.newDefaultAsyncResult(null, te, invocation);
258	            } else {
259	                asyncResult = AsyncRpcResult.newDefaultAsyncResult(null, e, invocation);
260	            }
261	        } catch (RpcException e) {
262	            // if biz exception
263	            if (e.isBiz()) {
264	                asyncResult = AsyncRpcResult.newDefaultAsyncResult(null, e, invocation);
265	            } else {
266	                throw e;
267	            }
268	        } catch (Throwable e) {
269	            asyncResult = AsyncRpcResult.newDefaultAsyncResult(null, e, invocation);
270	        }
271	
272	        if (setFutureWhenSync || invocation.getInvokeMode() != InvokeMode.SYNC) {
273	            // set server context
274	            RpcContext.getServiceContext().setFuture(new FutureAdapter<>(asyncResult.getResponseFuture()));
275	        }
276	
277	        return asyncResult;
278	    }
279	
280	    private void waitForResultIfSync(AsyncRpcResult asyncResult, RpcInvocation invocation) {
281	        if (InvokeMode.SYNC != invocation.getInvokeMode()) {
282	            return;
283	        }
284	        try {
285	            /*
286	             * NOTICE!
287	             * must call {@link java.util.concurrent.CompletableFuture#get(long, TimeUnit)} because
288	             * {@link java.util.concurrent.CompletableFuture#get()} was proved to have serious performance drop.
289	             */
290	            Object timeoutKey = invocation.getObjectAttachmentWithoutConvert(TIMEOUT_KEY);
291	            long timeout = RpcUtils.convertToNumber(timeoutKey, Integer.MAX_VALUE);
292	
293	            asyncResult.get(timeout, TimeUnit.MILLISECONDS);
294	        } catch (InterruptedException e) {
295	            Thread.currentThread().interrupt();
296	            throw new RpcException(
297	                    "Interrupted unexpectedly while waiting for remote result to return! method: "
298	                            + invocation.getMethodName() + ", provider: " + getUrl() + ", cause: " + e.getMessage(),
299	                    e);
300	        } catch (ExecutionException e) {
301	            Throwable rootCause = e.getCause();
302	            if (rootCause instanceof TimeoutException) {
303	                throw new RpcException(
304	                        RpcException.TIMEOUT_EXCEPTION,
305	                        "Invoke remote method timeout. method: " + invocation.getMethodName() + ", provider: "
306	                                + getUrl() + ", cause: " + e.getMessage(),
307	                        e);
308	            } else if (rootCause instanceof RemotingException) {
309	                throw new RpcException(
310	                        RpcException.NETWORK_EXCEPTION,
311	                        "Failed to invoke remote method: " + invocation.getMethodName() + ", provider: " + getUrl()
312	                                + ", cause: " + e.getMessage(),
313	                        e);
314	            } else if (rootCause instanceof SerializationException) {
315	                throw new RpcException(
316	                        RpcException.SERIALIZATION_EXCEPTION,
317	                        "Invoke remote method failed cause by serialization error.  remote method: "
318	                                + invocation.getMethodName() + ", provider: " + getUrl() + ", cause: " + e.getMessage(),
319	                        e);
320	            } else {
321	                throw new RpcException(
322	                        RpcException.UNKNOWN_EXCEPTION,
323	                        "Fail to invoke remote method: " + invocation.getMethodName() + ", provider: " + getUrl()
324	                                + ", cause: " + e.getMessage(),
325	                        e);
326	            }
327	        } catch (java.util.concurrent.TimeoutException e) {
328	            throw new RpcException(
329	                    RpcException.TIMEOUT_EXCEPTION,
330	                    "Invoke remote method timeout. method: " + invocation.getMethodName() + ", provider: " + getUrl()
331	                            + ", cause: " + e.getMessage(),
332	                    e);
333	        } catch (Throwable e) {
334	            throw new RpcException(e.getMessage(), e);
335	        }
336	    }
337	
338	    // -- Protected api
339	
340	    protected ExecutorService getCallbackExecutor(URL url, Invocation inv) {
341	        if (InvokeMode.SYNC == RpcUtils.getInvokeMode(getUrl(), inv)) {
342	            return new ThreadlessExecutor();
343	        }
344	        return ExecutorRepository.getInstance(url.getOrDefaultApplicationModel())
345	                .getExecutor(url);
346	    }
347	
348	    /**
349	     * Specific implementation of the {@link #invoke(Invocation)} method
350	     */
351	    protected abstract Result doInvoke(Invocation invocation) throws Throwable;
352	}
