126	    private static AsciiString getSchemeFromUrl(URL url) {
127	        boolean ssl = url.getParameter(CommonConstants.SSL_ENABLED_KEY, false);
128	        return ssl ? TripleConstants.HTTPS_SCHEME : TripleConstants.HTTP_SCHEME;
