131	    private static Compressor getCompressorFromEnv() {
132	        Compressor compressor = TripleInvoker.compressor;
133	        if (compressor == null) {
134	            ApplicationModel model = ApplicationModel.defaultModel();
135	            Configuration configuration = ConfigurationUtils.getEnvConfiguration(model);
136	            String compressorKey = configuration.getString(COMPRESSOR_KEY, Identity.MESSAGE_ENCODING);
137	            compressor = Compressor.getCompressor(ScopeModelUtil.getFrameworkModel(model), compressorKey);
138	            TripleInvoker.compressor = compressor;
