143	    @Override
144	    protected Result doInvoke(final Invocation invocation) {
145	        if (!connectionClient.isConnected()) {
146	            CompletableFuture<AppResponse> future = new CompletableFuture<>();
147	            RpcException exception = TriRpcStatus.UNAVAILABLE
148	                    .withDescription(String.format("upstream %s is unavailable", getUrl().getAddress()))
149	                    .asException();
150	            future.completeExceptionally(exception);
151	            return new AsyncRpcResult(future, invocation);
152	        }
153	
154	        ConsumerModel consumerModel = (ConsumerModel)
155	                (invocation.getServiceModel() != null ? invocation.getServiceModel() : getUrl().getServiceModel());
156	        ServiceDescriptor serviceDescriptor = consumerModel.getServiceModel();
157	        MethodDescriptor methodDescriptor =
158	                serviceDescriptor.getMethod(invocation.getMethodName(), invocation.getParameterTypes());
159	        if (methodDescriptor == null) {
160	            if (RpcUtils.isGenericCall(
161	                    ((RpcInvocation) invocation).getParameterTypesDesc(), invocation.getMethodName())) {
162	                // Only reach when server generic
163	                methodDescriptor = ServiceDescriptorInternalCache.genericService()
164	                        .getMethod(invocation.getMethodName(), invocation.getParameterTypes());
165	            } else if (RpcUtils.isEcho(
166	                    ((RpcInvocation) invocation).getParameterTypesDesc(), invocation.getMethodName())) {
167	                methodDescriptor = ServiceDescriptorInternalCache.echoService()
168	                        .getMethod(invocation.getMethodName(), invocation.getParameterTypes());
169	            }
170	        }
171	        ExecutorService callbackExecutor =
172	                isSync(methodDescriptor, invocation) ? new ThreadlessExecutor() : streamExecutor;
173	        ClientCall call = new TripleClientCall(
174	                connectionClient, callbackExecutor, getUrl().getOrDefaultFrameworkModel(), writeQueue);
175	        RpcContext.getServiceContext().setLocalAddress(connectionClient.getLocalAddress());
176	        AsyncRpcResult result;
177	        try {
178	            switch (methodDescriptor.getRpcType()) {
179	                case UNARY:
180	                    result = invokeUnary(methodDescriptor, invocation, call, callbackExecutor);
181	                    break;
182	                case SERVER_STREAM:
183	                    result = invokeServerStream(methodDescriptor, invocation, call);
184	                    break;
185	                case CLIENT_STREAM:
186	                case BI_STREAM:
187	                    result = invokeBiOrClientStream(methodDescriptor, invocation, call);
188	                    break;
189	                default:
190	                    throw new IllegalStateException("Can not reach here");
191	            }
192	            return result;
193	        } catch (Throwable t) {
194	            final TriRpcStatus status =
195	                    TriRpcStatus.INTERNAL.withCause(t).withDescription("Call aborted cause client exception");
196	            RpcException e = status.asException();
197	            try {
198	                call.cancelByLocal(e);
199	            } catch (Throwable t1) {
200	                LOGGER.error(PROTOCOL_FAILED_REQUEST, "", "", "Cancel triple request failed", t1);
201	            }
202	            CompletableFuture<AppResponse> future = new CompletableFuture<>();
203	            future.completeExceptionally(e);
204	            return new AsyncRpcResult(future, invocation);
205	        }
206	    }
