208	    private static boolean isSync(MethodDescriptor methodDescriptor, Invocation invocation) {
209	        if (!(invocation instanceof RpcInvocation)) {
210	            return false;
211	        }
212	        RpcInvocation rpcInvocation = (RpcInvocation) invocation;
213	        MethodDescriptor.RpcType rpcType = methodDescriptor.getRpcType();
214	        return UNARY.equals(rpcType) && InvokeMode.SYNC.equals(rpcInvocation.getInvokeMode());
215	    }
