217	    AsyncRpcResult invokeServerStream(MethodDescriptor methodDescriptor, Invocation invocation, ClientCall call) {
218	        RequestMetadata request = createRequest(methodDescriptor, invocation, null);
219	        Object[] arguments = invocation.getArguments();
220	        final StreamObserver<Object> requestObserver;
221	        if (arguments.length == 2) {
222	            StreamObserver<Object> responseObserver = (StreamObserver<Object>) arguments[1];
223	            requestObserver = streamCall(call, request, responseObserver);
224	            requestObserver.onNext(invocation.getArguments()[0]);
225	        } else if (arguments.length == 1) {
226	            StreamObserver<Object> responseObserver = (StreamObserver<Object>) arguments[0];
227	            requestObserver = streamCall(call, request, responseObserver);
228	            requestObserver.onNext(null);
229	        } else {
230	            throw new IllegalStateException(
231	                    "The first parameter must be a StreamObserver when there are no parameters, or the second parameter must be a StreamObserver when there are parameters");
232	        }
233	        requestObserver.onCompleted();
234	        return new AsyncRpcResult(CompletableFuture.completedFuture(new AppResponse()), invocation);
235	    }
