237	    AsyncRpcResult invokeBiOrClientStream(MethodDescriptor methodDescriptor, Invocation invocation, ClientCall call) {
238	        final AsyncRpcResult result;
239	        RequestMetadata request = createRequest(methodDescriptor, invocation, null);
240	        StreamObserver<Object> responseObserver =
241	                (StreamObserver<Object>) invocation.getArguments()[0];
242	        final StreamObserver<Object> requestObserver = streamCall(call, request, responseObserver);
243	        result = new AsyncRpcResult(CompletableFuture.completedFuture(new AppResponse(requestObserver)), invocation);
244	        return result;
245	    }
