247	    /**
248	     * Start a streaming call
249	     * <p>
250	     * The call sequence is:
251	     * <pre>
252	     * 1. Create adapter and listener
253	     * 2. Call beforeStart() if observer is ClientResponseObserver or CancelableStreamObserver
254	     *   (allows configuring onReadyHandler before stream starts)
255	     * 3. Start the call (creates stream, may trigger initial onReady)
256	     * </pre>
257	     *
258	     * <p>The two interfaces serve different purposes:
259	     * <ul>
260	     *   <li>{@link ClientResponseObserver} - gRPC-compatible interface with just beforeStart()
261	     *   <li>{@link CancelableStreamObserver} - Dubbo's extended interface with cancellation and startRequest()
262	     * </ul>
263	     * An observer can implement both interfaces (e.g., ClientTripleReactorPublisher).
264	     */
265	    @SuppressWarnings("unchecked")
266	    StreamObserver<Object> streamCall(
267	            ClientCall call, RequestMetadata metadata, StreamObserver<Object> responseObserver) {
268	        ClientCallToObserverAdapter<Object> adapter = new ClientCallToObserverAdapter<>(call, true);
269	
270	        // Create listener and associate with adapter
271	        ObserverToClientCallListenerAdapter listener = new ObserverToClientCallListenerAdapter(responseObserver);
272	        listener.setRequestAdapter(adapter);
273	
274	        // Handle CancelableStreamObserver first (for cancellation context and startRequest)
275	        // This must be done regardless of whether it also implements ClientResponseObserver
276	        if (responseObserver instanceof CancelableStreamObserver) {
277	            CancelableStreamObserver<Object> cancelableObserver = (CancelableStreamObserver<Object>) responseObserver;
278	            // Set up cancellation context
279	            CancellationContext context = new CancellationContext();
280	            cancelableObserver.setCancellationContext(context);
281	            context.addListener(ctx -> call.cancelByLocal(new IllegalStateException("Canceled by app")));
282	            // Set up startRequest to be called when stream is established (onStart)
283	            listener.setOnStartConsumer(dummy -> cancelableObserver.startRequest());
284	        }
285	
286	        // Now call beforeStart() - use ClientResponseObserver if available (gRPC-compatible),
287	        // otherwise fall back to CancelableStreamObserver.beforeStart()
288	        if (responseObserver instanceof ClientResponseObserver) {
289	            // gRPC-compatible interface - beforeStart takes ClientCallStreamObserver
290	            ClientResponseObserver<Object, Object> clientResponseObserver =
291	                    (ClientResponseObserver<Object, Object>) responseObserver;
292	            clientResponseObserver.beforeStart(adapter);
293	        } else if (responseObserver instanceof CancelableStreamObserver) {
294	            // Legacy Dubbo interface - beforeStart takes ClientCallToObserverAdapter
295	            CancelableStreamObserver<Object> cancelableObserver = (CancelableStreamObserver<Object>) responseObserver;
296	            cancelableObserver.beforeStart(adapter);
297	        }
298	
299	        // Start the call - creates stream and may trigger initial onReady
300	        call.start(metadata, listener);
301	
302	        return adapter;
303	    }
304	
305	    AsyncRpcResult invokeUnary(
306	            MethodDescriptor methodDescriptor,
307	            Invocation invocation,
308	            ClientCall call,
309	            ExecutorService callbackExecutor) {
310	
311	        int timeout = RpcUtils.calculateTimeout(getUrl(), invocation, RpcUtils.getMethodName(invocation), 3000);
312	        if (timeout <= 0) {
313	            return AsyncRpcResult.newDefaultAsyncResult(
314	                    new RpcException(
315	                            RpcException.TIMEOUT_TERMINATE,
316	                            "No time left for making the following call: " + invocation.getServiceName() + "."
317	                                    + RpcUtils.getMethodName(invocation) + ", terminate directly."),
318	                    invocation);
319	        }
320	        invocation.setAttachment(TIMEOUT_KEY, String.valueOf(timeout));
321	
322	        final AsyncRpcResult result;
323	        DeadlineFuture future = DeadlineFuture.newFuture(
324	                getUrl().getPath(), methodDescriptor.getMethodName(), getUrl().getAddress(), timeout, callbackExecutor);
325	
326	        RequestMetadata request = createRequest(methodDescriptor, invocation, timeout);
327	
328	        final Object pureArgument;
329	
330	        if (methodDescriptor instanceof StubMethodDescriptor) {
331	            pureArgument = invocation.getArguments()[0];
332	        } else {
333	            pureArgument = invocation.getArguments();
334	        }
335	        result = new AsyncRpcResult(future, invocation);
336	        if (setFutureWhenSync || ((RpcInvocation) invocation).getInvokeMode() != InvokeMode.SYNC) {
337	            FutureContext.getContext().setCompatibleFuture(future);
338	        }
339	
340	        result.setExecutor(callbackExecutor);
341	        ClientCall.Listener callListener = new UnaryClientCallListener(future);
342	
343	        // Create adapter for unary call (streamingResponse=false)
344	        ClientCallToObserverAdapter<Object> requestObserver = new ClientCallToObserverAdapter<>(call, false);
345	        call.start(request, callListener);
346	        requestObserver.onNext(pureArgument);
347	        requestObserver.onCompleted();
348	        return result;
349	    }
