351	    RequestMetadata createRequest(MethodDescriptor methodDescriptor, Invocation invocation, Integer timeout) {
352	        final String methodName = RpcUtils.getMethodName(invocation);
353	        Objects.requireNonNull(
354	                methodDescriptor,
355	                "MethodDescriptor not found for" + methodName + " params:"
356	                        + Arrays.toString(invocation.getCompatibleParamSignatures()));
357	        final RequestMetadata meta = new RequestMetadata();
358	        final URL url = getUrl();
359	        if (methodDescriptor instanceof PackableMethod) {
360	            meta.packableMethod = (PackableMethod) methodDescriptor;
361	        } else {
362	            meta.packableMethod = ConcurrentHashMapUtils.computeIfAbsent(
363	                    packableMethodCache,
364	                    methodDescriptor,
365	                    (md) -> packableMethodFactory.create(md, url, APPLICATION_GRPC_PROTO.getName()));
366	        }
367	        meta.convertNoLowerHeader = TripleProtocol.CONVERT_NO_LOWER_HEADER;
368	        meta.ignoreDefaultVersion = TripleProtocol.IGNORE_1_0_0_VERSION;
369	        meta.method = methodDescriptor;
370	        meta.scheme = getSchemeFromUrl(url);
371	        meta.compressor = getCompressorFromEnv();
372	        meta.cancellationContext = RpcContext.getCancellationContext();
373	        meta.address = url.getAddress();
374	        meta.service = url.getPath();
375	        meta.group = url.getGroup();
376	        meta.version = url.getVersion();
377	        meta.acceptEncoding = acceptEncodings;
378	        if (timeout != null) {
379	            meta.timeout = GrpcUtils.getTimeoutHeaderValue(Long.valueOf(timeout), TimeUnit.MILLISECONDS);
380	        }
381	        String application = (String) invocation.getObjectAttachmentWithoutConvert(CommonConstants.APPLICATION_KEY);
382	        if (application == null) {
383	            application = (String) invocation.getObjectAttachmentWithoutConvert(CommonConstants.REMOTE_APPLICATION_KEY);
384	        }
385	        meta.application = application;
386	        meta.attachments = invocation.getObjectAttachments();
387	        return meta;
388	    }
