392	        if (!super.isAvailable()) {
393	            return false;
394	        }
395	        if (!connectionClient.isConnected()) {
396	            return false;
397	        }
398	        if (connectionClient.hasAttribute(Constants.CHANNEL_ATTRIBUTE_READONLY_KEY)) {
399	            return false;
400	        }
401	        return true;
402	    }
